<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="dark">
<title>claude-haiku-5.5 · 다음 토큰의 바다</title>
<style>
:root{
  --bg:#0b0d14;
  --panel:rgba(16,19,30,.9);
  --fg:#f1f3fa;
  --muted:#c3c9da;
  --accent:#ffbf73;
  --accent2:#8fe0ff;
  --focus:#ffe066;
  --line:rgba(255,255,255,.14);
}
*{box-sizing:border-box}
html,body{margin:0;height:100%;background:var(--bg);color:var(--fg);
  font-family:system-ui,-apple-system,"Segoe UI","Apple SD Gothic Neo","Malgun Gothic",sans-serif;
  font-size:100%;line-height:1.6;overflow:hidden}
canvas{position:fixed;inset:0;width:100%;height:100%;display:block}

.skip{position:absolute;left:-9999px;top:auto}
.skip:focus{left:1rem;top:1rem;z-index:20;background:#fff;color:#000;padding:.6rem 1rem;border-radius:.4rem}

.panel{
  position:fixed;left:1rem;right:1rem;bottom:1rem;z-index:5;
  max-height:46vh;overflow:auto;
  background:var(--panel);border:1px solid var(--line);border-radius:1rem;
  padding:clamp(1rem,2.5vw,1.5rem);
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);
}
@media (min-width:768px){
  .panel{left:1.5rem;bottom:1.5rem;right:auto;width:min(28rem,calc(100vw - 3rem));max-height:calc(100vh - 3rem)}
}
h1{margin:0 0 .25rem;font-size:clamp(1.2rem,1rem + 1vw,1.75rem);line-height:1.3}
.model{display:inline-block;margin:.25rem 0 .75rem;padding:.2rem .6rem;border-radius:.4rem;
  background:rgba(255,191,115,.14);color:var(--accent);font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:.95rem;font-weight:600}
p{margin:.5rem 0;color:var(--muted);font-size:.98rem}

.controls{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:.9rem}
button{
  min-height:44px;min-width:44px;padding:.5rem .9rem;border-radius:.6rem;
  border:1px solid var(--line);background:#1d2233;color:var(--fg);font:inherit;cursor:pointer
}
button:hover{background:#27304a}
button[aria-pressed="true"]{background:var(--accent);color:#14110b;border-color:var(--accent)}
:focus-visible{outline:3px solid var(--focus);outline-offset:3px}

.row{display:flex;flex-direction:column;gap:.4rem;margin-top:1rem}
.row label{font-weight:600}
input[type=range]{width:100%;min-height:44px;accent-color:var(--accent2)}
.hint{font-size:.85rem;color:var(--muted)}
.tiny{font-size:.8rem;color:#aab1c6;margin-top:.8rem;font-family:ui-monospace,Consolas,monospace;word-break:break-all}

.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

@media (prefers-reduced-motion:reduce){
  *{transition:none!important;animation:none!important}
}
</style>
</head>
<body>

<a class="skip" href="#panel">조작 패널로 건너뛰기</a>

<canvas id="field" role="img" aria-label="수많은 단어 조각이 흐르고 서로 이어지는 추상 화면. 설명은 패널에 있습니다."></canvas>

<section class="panel" id="panel" aria-labelledby="title">
  <h1 id="title">다음 토큰의 바다</h1>
  <span class="model">claude-haiku-5.5</span>
  <p>
    나는 Claude Haiku 5.5입니다. 나는 문장을 한 번에 이해하지 않고, 조각난 토큰을 하나씩 잇습니다.
    수많은 가능성이 흐르는 바다에서 어떤 조각이 다음에 올지 확률로 고르고, 그 선택이 다시 문맥이 됩니다.
  </p>
  <p class="hint">온도(temperature)를 올리면 바다는 더 흔들리고, 낮추면 흐름이 차분해집니다. 화면을 누르거나 드래그해 토큰을 끌어당겨 보세요.</p>

  <div class="row">
    <label for="temp">온도 <span id="tempOut">0.70</span></label>
    <input type="range" id="temp" min="0" max="100" value="70" aria-describedby="tempHint">
    <span id="tempHint" class="hint">0에 가까우면 예측 가능하고, 100에 가까우면 예측하기 어려워집니다.</span>
  </div>

  <div class="controls">
    <button type="button" id="pause" aria-pressed="false">일시정지 (P)</button>
    <button type="button" id="reset">다시 섞기 (R)</button>
    <button type="button" id="calm" aria-pressed="false">움직임 줄이기</button>
  </div>

  <p class="tiny">모델 식별자: us.anthropic.claude-haiku-5-5</p>
</section>

<div class="sr-only" aria-live="polite" id="live"></div>

<script>
(() => {
  const canvas = document.getElementById('field');
  const ctx = canvas.getContext('2d');
  const tempInput = document.getElementById('temp');
  const tempOut = document.getElementById('tempOut');
  const pauseBtn = document.getElementById('pause');
  const resetBtn = document.getElementById('reset');
  const calmBtn = document.getElementById('calm');
  const live = document.getElementById('live');

  const WORDS = ['생각','문맥','확률','다음','의미','관계','이해','언어','질문','답',
    '온도','균형','그럴듯한','연결','흐름','조각','tokens','context','attention','probably','hello','softmax'];
  const HUES = [28, 195, 265];

  const reduceQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
  let calm = reduceQuery.matches;
  let running = !calm ? true : true;
  let W = 0, H = 0, DPR = 1, count = 0;
  let particles = [];
  let ripples = [];
  let time = 0;
  let pointer = { x: -1e4, y: -1e4, active: false };
  let temperature = 0.7;

  function rand(a, b) { return a + Math.random() * (b - a); }

  function spawn(initial) {
    const hue = HUES[Math.floor(Math.random() * HUES.length)];
    return {
      x: rand(0, W),
      y: initial ? rand(0, H) : -20,
      vx: 0, vy: 0,
      word: WORDS[Math.floor(Math.random() * WORDS.length)],
      size: rand(12, 22) * (W < 600 ? 0.9 : 1),
      hue,
      phase: rand(0, Math.PI * 2),
      alpha: rand(0.45, 1)
    };
  }

  function resize() {
    DPR = Math.min(window.devicePixelRatio || 1, 2);
    W = window.innerWidth;
    H = window.innerHeight;
    canvas.width = Math.floor(W * DPR);
    canvas.height = Math.floor(H * DPR);
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    count = Math.max(40, Math.min(150, Math.round((W * H) / 10000)));
    particles = Array.from({ length: count }, () => spawn(true));
    ctx.fillStyle = '#0b0d14';
    ctx.fillRect(0, 0, W, H);
  }

  function flow(x, y, t) {
    const k = 0.0032;
    return [
      Math.sin(x * k + t * 0.3) + Math.cos(y * k * 1.3 - t * 0.2),
      Math.cos(x * k * 0.9 - t * 0.25) + Math.sin(y * k * 1.1 + t * 0.15)
    ];
  }

  function step() {
    const T = temperature;
    const speed = calm ? 0.25 : 1;
    const jitter = calm ? 0 : T * 0.7;

    for (const p of particles) {
      const [fx, fy] = flow(p.x, p.y, time);
      p.vx += fx * 0.02 * speed + (Math.random() - 0.5) * jitter * speed;
      p.vy += fy * 0.02 * speed + (Math.random() - 0.5) * jitter * speed;

      if (pointer.active) {
        const dx = pointer.x - p.x, dy = pointer.y - p.y;
        const d2 = dx * dx + dy * dy;
        const R = 200;
        if (d2 < R * R && d2 > 1) {
          const d = Math.sqrt(d2);
          const f = (1 - d / R) * 0.9;
          p.vx += (dx / d) * f;
          p.vy += (dy / d) * f;
        }
      }

      p.vx *= 0.93;
      p.vy *= 0.93;
      p.x += p.vx;
      p.y += p.vy;

      if (p.x < -60) p.x = W + 60;
      if (p.x > W + 60) p.x = -60;
      if (p.y < -60) p.y = H + 60;
      if (p.y > H + 60) p.y = -60;
    }

    for (const r of ripples) {
      r.r += 3 * speed;
      r.a -= 0.012 * speed;
    }
    ripples = ripples.filter(r => r.a > 0);
  }

  function draw() {
    ctx.fillStyle = 'rgba(11,13,20,0.22)';
    ctx.fillRect(0, 0, W, H);

    const linkMax = 90;
    const n = Math.min(particles.length, 70);
    ctx.lineWidth = 1;
    for (let i = 0; i < n; i++) {
      const a = particles[i];
      for (let j = i + 1; j < n; j++) {
        const b = particles[j];
        const dx = a.x - b.x, dy = a.y - b.y;
        const d2 = dx * dx + dy * dy;
        if (d2 < linkMax * linkMax) {
          const alpha = (1 - Math.sqrt(d2) / linkMax) * 0.22;
          ctx.strokeStyle = `hsla(${a.hue},70%,70%,${alpha})`;
          ctx.beginPath();
          ctx.moveTo(a.x, a.y);
          ctx.lineTo(b.x, b.y);
          ctx.stroke();
        }
      }
    }

    for (const r of ripples) {
      ctx.strokeStyle = `rgba(255,191,115,${Math.max(r.a, 0)})`;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(r.x, r.y, r.r, 0, Math.PI * 2);
      ctx.stroke();
    }

    ctx.textBaseline = 'middle';
    ctx.textAlign = 'center';
    for (const p of particles) {
      const pulse = calm ? 0.8 : 0.5 + 0.5 * Math.sin(p.phase + time * 1.5);
      const alpha = p.alpha * pulse;
      ctx.font = `600 ${p.size}px system-ui, "Apple SD Gothic Neo", "Malgun Gothic", sans-serif`;
      ctx.fillStyle = `hsla(${p.hue},80%,${p.hue === 28 ? 72 : 78}%,${alpha})`;
      ctx.fillText(p.word, p.x, p.y);
    }
  }

  let last = 0;
  function frame(ts) {
    if (running) {
      if (ts - last > 16) {
        time += calm ? 0.004 : 0.012;
        step();
        draw();
        last = ts;
      }
    }
    requestAnimationFrame(frame);
  }

  function setTemp(v) {
    temperature = v / 100;
    tempOut.textContent = temperature.toFixed(2);
    tempInput.setAttribute('aria-valuetext', `온도 ${temperature.toFixed(2)}`);
  }

  function setPaused(p) {
    running = !p;
    pauseBtn.setAttribute('aria-pressed', String(p));
    pauseBtn.textContent = p ? '재생 (P)' : '일시정지 (P)';
    announce(p ? '일시정지됨' : '재생 중');
  }

  function setCalm(c) {
    calm = c;
    calmBtn.setAttribute('aria-pressed', String(c));
    announce(c ? '움직임 줄이기 켜짐' : '움직임 줄이기 꺼짐');
  }

  let announceTimer = 0;
  function announce(msg) {
    clearTimeout(announceTimer);
    announceTimer = setTimeout(() => { live.textContent = msg; }, 150);
  }

  function reshuffle() {
    particles = Array.from({ length: count }, () => spawn(true));
    ripples = [];
    announce('토큰을 다시 섞었습니다');
  }

  function pointerPos(e) {
    const rect = canvas.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  }

  canvas.addEventListener('pointerdown', e => {
    pointer = { ...pointerPos(e), active: true };
    if (!calm) ripples.push({ x: pointer.x, y: pointer.y, r: 4, a: 0.8 });
    const word = WORDS[Math.floor(Math.random() * WORDS.length)];
    particles.push({ ...spawn(false), x: pointer.x, y: pointer.y, word });
    if (particles.length > 200) particles.shift();
  });
  canvas.addEventListener('pointermove', e => {
    if (pointer.active) pointer = { ...pointerPos(e), active: true };
  });
  const endPointer = () => { pointer.active = false; };
  canvas.addEventListener('pointerup', endPointer);
  canvas.addEventListener('pointercancel', endPointer);
  canvas.addEventListener('pointerleave', endPointer);

  tempInput.addEventListener('input', e => setTemp(Number(e.target.value)));
  pauseBtn.addEventListener('click', () => setPaused(running));
  resetBtn.addEventListener('click', reshuffle);
  calmBtn.addEventListener('click', () => setCalm(!calm));

  document.addEventListener('keydown', e => {
    if (e.target.matches('input, button, textarea')) {
      if (e.key !== 'Escape') return;
    }
    const k = e.key.toLowerCase();
    if (k === 'p') setPaused(running);
    else if (k === 'r') reshuffle();
    else if (k === 'c') setCalm(!calm);
    else if (k === 'arrowup' || k === '+' || k === '=') { e.preventDefault(); adjustTemp(5); }
    else if (k === 'arrowdown' || k === '-') { e.preventDefault(); adjustTemp(-5); }
  });

  function adjustTemp(delta) {
    const v = Math.min(100, Math.max(0, Number(tempInput.value) + delta));
    tempInput.value = v;
    setTemp(v);
  }

  reduceQuery.addEventListener('change', e => setCalm(e.matches));
  window.addEventListener('resize', resize);

  calmBtn.setAttribute('aria-pressed', String(calm));
  setTemp(70);
  resize();
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
